void Entry::removeHistoryItems(QList<Entry*> historyEntries)
{
    bool emitModified = historyEntries.count() > 0;
    Q_FOREACH (Entry* entry, historyEntries) {
        Q_ASSERT(!entry->parent());
        Q_ASSERT(entry->uuid() == uuid());
        Q_ASSERT(m_history.removeAll(entry) > 0);
        delete entry;
    }

    if (emitModified) {
        Q_EMIT modified();
    }
}

void Entry::truncateHistory()
{
    const Database* db = database();

    if (!db) {
        return;
    }

    int histMaxItems = db->metadata()->historyMaxItems();
    if (histMaxItems > -1) {
        int historyCount = 0;
        QMutableListIterator<Entry*> i(m_history);
        i.toBack();
        while (i.hasPrevious()) {
            historyCount++;
            Entry* entry = i.previous();
            if (historyCount > histMaxItems) {
                delete entry;
                i.remove();
            }
        }
    }

    int histMaxSize = db->metadata()->historyMaxSize();
    if (histMaxSize > -1) {
        int size = 0;
        QList<QByteArray> foundAttachements;
        attachments()->attachmentsSize(&foundAttachements);

        QMutableListIterator<Entry*> i(m_history);
        i.toBack();
        while (i.hasPrevious()) {
            Entry* entry = i.previous();

            // don't calculate size if it's already above the maximum
            if (size <= histMaxSize) {
                size += entry->getSize(&foundAttachements);
            }

            if (size > histMaxSize) {
                delete entry;
                i.remove();
            }
        }
    }
}

