     QFile file(filename);
     if (!file.open(QFile::ReadOnly)) {
         raiseError(file.errorString());
         return 0;
     }

     QScopedPointer<Database> db(readDatabase(&file, password, keyfileData));

     if (file.error() != QFile::NoError) {
         raiseError(file.errorString());
         return 0;
     }

