 void TestEntry::testHistoryItemDeletion()
 {
     Entry* entry = new Entry();
     QPointer<Entry> historyEntry = new Entry();

     entry->addHistoryItem(historyEntry);
     QCOMPARE(entry->historyItems().size(), 1);

